// `build/server` is generated by `remix vite:build`, and the compiler would
// infer a looser type from its JavaScript. Declaring the module here makes the
// Pages function type-check against `ServerBuild` identically before and after
// a build. The tsconfig `server-build` path maps to the real output and falls
// back to this file so lint can resolve the import from a clean checkout.
declare module "server-build" {
  import type { ServerBuild } from "@remix-run/cloudflare";

  export const assets: ServerBuild["assets"];
  export const assetsBuildDirectory: ServerBuild["assetsBuildDirectory"];
  export const entry: ServerBuild["entry"];
  export const future: ServerBuild["future"];
  export const isSpaMode: ServerBuild["isSpaMode"];
  export const mode: ServerBuild["mode"];
  export const publicPath: ServerBuild["publicPath"];
  export const routes: ServerBuild["routes"];
}
